import { Readable } from 'node:stream';
export class DynamicBufferReadable extends Readable {
    #buffers;
    #index;
    constructor(buffers) {
        super();
        this.#buffers = buffers.slice();
        this.#index = 0;
    }
    _read(_size) {
        while (this.#index < this.#buffers.length) {
            if (!this.push(this.#buffers[this.#index++])) {
                return;
            }
        }
        this.push(null);
    }
}
